// Review sheets from the last 45 days that are not closed. No ✅ reaction needed any more (Maria 2026-11-10):
// every hour each open sheet is re-read and every row with a Decision (and a reason when rejected) is stored as a learning.
const cutoff = Date.now() - 45 * 86400000;
const seen = {}; const out = [];
for (const it of $input.all()) {
  const r = it.json || {};
  if (!r.sheet_id || String(r.ingested || '') === 'yes') { continue; }
  const t = r.audited_at ? new Date(r.audited_at).getTime() : 0;
  if (t && t < cutoff) { continue; }
  if (seen[r.sheet_id]) { continue; }
  seen[r.sheet_id] = true;
  out.push({ json: { sheet_id: r.sheet_id, project_name: r.project_name || '', slack_ts: String(r.slack_ts || ''), prev: String(r.ingested || '') } });
}
return out;

// Turns every decided row of the open review sheets into a row of the 'i18n audit learnings' sheet (tab All).
// Approved/Apply -> Approved; Rejected/Reject -> Rejected (a reason is required; rows without one are listed back, not stored).
// Rows already stored (same Source) are skipped, so re-reading a sheet every hour is safe.
const LANG = { czech:'cs', danish:'da', german:'de', greek:'el', spanish:'es', estonian:'et', finnish:'fi', filipino:'fil', french:'fr', croatian:'hr', hungarian:'hu', indonesian:'id', italian:'it', korean:'ko', lithuanian:'lt', latvian:'lv', malay:'ms', dutch:'nl', norwegian:'no', polish:'pl', portuguese:'pt', romanian:'ro', slovak:'sk', slovenian:'sl', swedish:'sv', thai:'th', turkish:'tr', ukrainian:'uk', vietnamese:'vi' };
function isoOf(name) { const n = String(name || '').toLowerCase(); for (const k in LANG) { if (n.indexOf(k) === 0) { return LANG[k]; } } return ''; }
function hash(s) { let h = 5381; for (let i = 0; i < s.length; i++) { h = ((h << 5) + h + s.charCodeAt(i)) | 0; } return (h >>> 0).toString(36); }
const pend = $('Pending reviews').all().map(function (i) { return i.json; });
const reads = $('Read review tabs').all().map(function (i) { return i.json || {}; });
const L = ($('Read learnings').first().json || {}).values || [];
const seen = {}; let maxN = 0;
for (const r of L.slice(1)) { if (r[13]) { seen[r[13]] = true; } const m = /^L(\d+)$/.exec(String(r[0] || '')); if (m) { maxN = Math.max(maxN, Number(m[1])); } }
const today = $now.setZone('Europe/Madrid').toFormat('yyyy-MM-dd');
const rows = []; const perSheet = [];
for (let i = 0; i < pend.length; i++) {
  const p = pend[i]; const vr = (reads[i] && reads[i].valueRanges) || [];
  const missing = []; let stored = 0; let decided = 0;
  for (const r of vr) {
    const vals = r.values || []; if (!vals.length) { continue; }
    const head = vals[0].map(String);
    const reasonCol = head.findIndex(function (h) { return /^reason/i.test(h); });
    for (let k = 1; k < vals.length; k++) {
      const o = {}; for (let c = 0; c < head.length; c++) { o[head[c]] = vals[k][c] === undefined ? '' : String(vals[k][c]); }
      if (!o.Key && !o.Check) { continue; }
      const dec = String(o.Decision || '').trim().toLowerCase();
      const app = dec === 'approved' || dec === 'apply'; const rej = dec === 'rejected' || dec === 'reject';
      if (!app && !rej) { continue; }
      decided++;
      const reason = reasonCol >= 0 ? String(vals[k][reasonCol] || '').trim() : '';
      if (rej && !reason) { missing.push('• ' + (o.Language || '') + ' — ' + (o.Key || '') + ' (' + (o['Rule / term'] || o.Check || '') + ')'); continue; }
      const src = 'sheet:' + p.sheet_id + '#' + hash([o.Project, o.Language, o.Key, o['Rule / term'], o.Issue].join('|'));
      if (seen[src]) { continue; }
      seen[src] = true; maxN++; stored++;
      rows.push(['L' + String(maxN).padStart(5, '0'), o.Language || '', o.ISO || isoOf(o.Language), 'All products', app ? 'Approved' : 'Rejected', o['Rule / term'] || o.Check || '', String(o.English || '').slice(0, 2000), String(o.Translation || '').slice(0, 2000), String(o.Issue || '').slice(0, 1000), reason, 'Yes', today, o.Project || p.project_name, src]);
    }
  }
  perSheet.push({ sheet_id: p.sheet_id, slack_ts: p.slack_ts, prev: p.prev, stored: stored, decided: decided, missing: missing });
}
return [{ json: { rows: rows, perSheet: perSheet } }];

// One item per open review sheet: Slack thread message (if any) and the new review state.
const NL = String.fromCharCode(10);
const b = $('Build learnings').first().json;
return b.perSheet.map(function (s) {
  const msg = [];
  if (s.stored) { msg.push(':brain: Stored ' + s.stored + ' reviewed decision(s) in the audit learnings sheet — future audits follow them: https://docs.google.com/spreadsheets/d/1hKJwT4MrNZymmiy9SA-aW2f6xRmWNJH0z6D65nwSrsk/edit'); }
  let state = s.prev;
  if (s.missing.length) {
    if (s.prev !== 'needs_reason') { msg.push(':warning: ' + s.missing.length + ' row(s) are marked *Rejected* without a reason, so they are not stored yet. Add a reason and they are picked up within the hour:' + NL + s.missing.slice(0, 15).join(NL) + (s.missing.length > 15 ? NL + '… and ' + (s.missing.length - 15) + ' more' : '')); }
    state = 'needs_reason';
  } else if (s.prev === 'needs_reason') { state = 'no'; }
  return { json: { sheet_id: s.sheet_id, slack_ts: s.slack_ts, msg: s.slack_ts ? msg.join(NL + NL) : '', new_state: state, state_changed: state !== s.prev ? 'yes' : 'no' } };
});

